package oop.class_problems;
public class AttendanceSystem {
    static class SrmStudent { String name, regNo; int attendance; SrmStudent(String name,String regNo,int attendance){this.name=name;this.regNo=regNo;this.attendance=attendance;} void addAttendanceUpdate(int newAttendance){attendance=newAttendance;} boolean isEligible(){return attendance>=75;} static double classAverage(SrmStudent[] s){double sum=0;for(SrmStudent x:s)sum+=x.attendance;return sum/s.length;} }
    public static void main(String[]a){SrmStudent[] s={new SrmStudent("Ravi","R1",82),new SrmStudent("Anitha","R2",68),new SrmStudent("Karthik","R3",91),new SrmStudent("Meera","R4",74),new SrmStudent("Suresh","R5",60)};for(SrmStudent x:s)System.out.println(x.name+" - "+x.attendance+"% - "+(x.isEligible()?"Eligible":"Detained"));System.out.println("Class average: "+SrmStudent.classAverage(s)+"%");}
}